/**
 * A simplified map of the world for the location section.
 *
 * Country outlines come from Natural Earth, which is in the public domain. Every path is drawn in a
 * 1000 by 394 box, with longitude running across and latitude from 84 to -58 running down.
 * The Philippines is kept apart so it can be drawn larger than the rest.
 */
export const WORLD_W = 1000;
export const WORLD_H = 394;

/** Turns a longitude and latitude into a position in the box, as a percentage of its width and height. */
export const worldPercent = (lon: number, lat: number) => ({
  left: ((lon + 180) / 360) * 100,
  top: ((84 - lat) / (142)) * 100,
});

